// CoreServiceServer is the server API for CoreService service.
// All implementations should embed UnimplementedCoreServiceServer
// for forward compatibility.
//
// CoreService handles device management, protocol operations, analytics,
// monitoring, certificates, blueprints, and integrations.
type CoreServiceServer interface {
	// End Point management
	CreateEndPoint(context.Context, *CreateEndPointRequest) (*EndPoint, error)
	GetEndPoint(context.Context, *GetEndPointRequest) (*EndPoint, error)
	UpdateEndPoint(context.Context, *UpdateEndPointRequest) (*EndPoint, error)
	DeleteEndPoint(context.Context, *DeleteEndPointRequest) (*emptypb.Empty, error)
	ListEndPoints(context.Context, *ListEndPointsRequest) (*ListEndPointsResponse, error)
	// End Point attach/detach operations
	AttachEndPoint(context.Context, *AttachEndPointRequest) (*AttachEndPointResponse, error)
	DetachEndPoint(context.Context, *DetachEndPointRequest) (*DetachEndPointResponse, error)
	// Base Station management
	CreateBaseStation(context.Context, *CreateBaseStationRequest) (*BaseStation, error)
	GetBaseStation(context.Context, *GetBaseStationRequest) (*BaseStation, error)
	UpdateBaseStation(context.Context, *UpdateBaseStationRequest) (*BaseStation, error)
	DeleteBaseStation(context.Context, *DeleteBaseStationRequest) (*emptypb.Empty, error)
	ListBaseStations(context.Context, *ListBaseStationsRequest) (*ListBaseStationsResponse, error)
	GetBaseStationStats(context.Context, *GetBaseStationStatsRequest) (*GetBaseStationStatsResponse, error)
	UpdateBaseStationEui(context.Context, *UpdateBaseStationEuiRequest) (*BaseStation, error)
	// Per-bucket availability (online fraction) time series for a base station.
	GetBaseStationAvailability(context.Context, *GetBaseStationAvailabilityRequest) (*GetBaseStationAvailabilityResponse, error)
	// Per-bucket received-message (RX uplink) counts time series for a base station.
	GetBaseStationMessagesReceived(context.Context, *GetBaseStationMessagesReceivedRequest) (*GetBaseStationMessagesReceivedResponse, error)
	// Message operations
	GetMessage(context.Context, *GetMessageRequest) (*Message, error)
	// Downlink operations
	SendDownlink(context.Context, *SendDownlinkRequest) (*SendDownlinkResponse, error)
	RevokeDownlink(context.Context, *RevokeDownlinkRequest) (*RevokeDownlinkResponse, error)
	ListDownlinkQueue(context.Context, *ListDownlinkQueueRequest) (*ListDownlinkQueueResponse, error)
	GetDownlinkResults(context.Context, *GetDownlinkResultsRequest) (*GetDownlinkResultsResponse, error)
	// UL Data Transmit operations (BSSCI 3.11)
	SendULTransmit(context.Context, *SendULTransmitRequest) (*SendULTransmitResponse, error)
	// Base Station operations (BSSCI 3.5)
	RequestBaseStationStatus(context.Context, *BaseStationStatusRequest) (*BaseStationStatusResponse, error)
	// Base Station Ping operation (BSSCI §5.4)
	InitiatePing(context.Context, *InitiatePingRequest) (*InitiatePingResponse, error)
	// DL RX Status operations (BSSCI 3.15-3.16)
	GetDLRXStatus(context.Context, *GetDLRXStatusRequest) (*GetDLRXStatusResponse, error)
	QueryDLRXStatus(context.Context, *QueryDLRXStatusRequest) (*QueryDLRXStatusResponse, error)
	GetDLRXStatusQueries(context.Context, *GetDLRXStatusQueriesRequest) (*GetDLRXStatusQueriesResponse, error)
	// System operations
	GetSystemStatus(context.Context, *emptypb.Empty) (*SystemStatus, error)
	GetStatistics(context.Context, *GetStatisticsRequest) (*Statistics, error)
	GetReleaseInfo(context.Context, *emptypb.Empty) (*ReleaseInfo, error)
	// Integrations
	CreateIntegration(context.Context, *CreateIntegrationRequest) (*Integration, error)
	GetIntegration(context.Context, *GetIntegrationRequest) (*Integration, error)
	UpdateIntegration(context.Context, *UpdateIntegrationRequest) (*Integration, error)
	DeleteIntegration(context.Context, *DeleteIntegrationRequest) (*emptypb.Empty, error)
	ListIntegrations(context.Context, *ListIntegrationsRequest) (*ListIntegrationsResponse, error)
	// Analytics
	GetAnalyticsOverview(context.Context, *GetAnalyticsOverviewRequest) (*GetAnalyticsOverviewResponse, error)
	GetActivityAnalytics(context.Context, *GetActivityAnalyticsRequest) (*GetActivityAnalyticsResponse, error)
	GetSignalQualityAnalytics(context.Context, *GetSignalQualityAnalyticsRequest) (*GetSignalQualityAnalyticsResponse, error)
	// Events & Alerts
	ListEvents(context.Context, *ListEventsRequest) (*ListEventsResponse, error)
	// Unified Activity Feed (Events + Messages with pagination)
	ListBaseStationActivity(context.Context, *ListBaseStationActivityRequest) (*ListBaseStationActivityResponse, error)
	ListEndpointActivity(context.Context, *ListEndpointActivityRequest) (*ListEndpointActivityResponse, error)
	// Event streaming RPCs
	StreamEvents(*StreamEventsRequest, grpc.ServerStreamingServer[Event]) error
	ListAlerts(context.Context, *ListAlertsRequest) (*ListAlertsResponse, error)
	GetAlertSummary(context.Context, *GetAlertSummaryRequest) (*GetAlertSummaryResponse, error)
	// SCACI Monitoring
	ListScaciSessions(context.Context, *ListScaciSessionsRequest) (*ListScaciSessionsResponse, error)
	GetScaciSession(context.Context, *GetScaciSessionRequest) (*GetScaciSessionResponse, error)
	GetScaciStatistics(context.Context, *GetScaciStatisticsRequest) (*GetScaciStatisticsResponse, error)
	ListScaciErrors(context.Context, *ListScaciErrorsRequest) (*ListScaciErrorsResponse, error)
	ListScaciQueues(context.Context, *ListScaciQueuesRequest) (*ListScaciQueuesResponse, error)
	GetScaciStatus(context.Context, *GetScaciStatusRequest) (*GetScaciStatusResponse, error)
	// Certificates
	GenerateCertificate(context.Context, *GenerateCertificateRequest) (*GenerateCertificateResponse, error)
	DownloadCertificate(context.Context, *DownloadCertificateRequest) (*DownloadCertificateResponse, error)
	DownloadBaseStationCertificate(context.Context, *DownloadBaseStationCertificateRequest) (*DownloadCertificateResponse, error)
	GenerateServerCertificates(context.Context, *GenerateServerCertificatesRequest) (*GenerateServerCertificatesResponse, error)
	RenewServerCertificates(context.Context, *RenewServerCertificatesRequest) (*RenewServerCertificatesResponse, error)
	GetServerCertificateStatus(context.Context, *GetServerCertificateStatusRequest) (*GetServerCertificateStatusResponse, error)
	// Blueprints / Device Catalog - Manufacturers
	CreateManufacturer(context.Context, *CreateManufacturerRequest) (*CreateManufacturerResponse, error)
	GetManufacturer(context.Context, *GetManufacturerRequest) (*GetManufacturerResponse, error)
	UpdateManufacturer(context.Context, *UpdateManufacturerRequest) (*UpdateManufacturerResponse, error)
	DeleteManufacturer(context.Context, *DeleteManufacturerRequest) (*DeleteManufacturerResponse, error)
	ListManufacturers(context.Context, *ListManufacturersRequest) (*ListManufacturersResponse, error)
	// Blueprints / Device Catalog - Device Models
	CreateDeviceModel(context.Context, *CreateDeviceModelRequest) (*CreateDeviceModelResponse, error)
	GetDeviceModel(context.Context, *GetDeviceModelRequest) (*GetDeviceModelResponse, error)
	UpdateDeviceModel(context.Context, *UpdateDeviceModelRequest) (*UpdateDeviceModelResponse, error)
	DeleteDeviceModel(context.Context, *DeleteDeviceModelRequest) (*DeleteDeviceModelResponse, error)
	ListDeviceModels(context.Context, *ListDeviceModelsRequest) (*ListDeviceModelsResponse, error)
	// Blueprints / Device Catalog - Blueprints
	CreateBlueprint(context.Context, *CreateBlueprintRequest) (*CreateBlueprintResponse, error)
	GetBlueprint(context.Context, *GetBlueprintRequest) (*GetBlueprintResponse, error)
	UpdateBlueprint(context.Context, *UpdateBlueprintRequest) (*UpdateBlueprintResponse, error)
	DeleteBlueprint(context.Context, *DeleteBlueprintRequest) (*DeleteBlueprintResponse, error)
	ListBlueprints(context.Context, *ListBlueprintsRequest) (*ListBlueprintsResponse, error)
	SetDefaultBlueprint(context.Context, *SetDefaultBlueprintRequest) (*SetDefaultBlueprintResponse, error)
	SubmitBlueprintToRegistry(context.Context, *SubmitBlueprintToRegistryRequest) (*SubmitBlueprintToRegistryResponse, error)
	BulkAssignBlueprint(context.Context, *BulkAssignBlueprintRequest) (*BulkAssignBlueprintResponse, error)
	// Composite: Create device model + default blueprint atomically
	CreateDeviceModelWithBlueprint(context.Context, *CreateDeviceModelWithBlueprintRequest) (*CreateDeviceModelWithBlueprintResponse, error)
	// Blueprint decode preview
	DecodePreview(context.Context, *DecodePreviewRequest) (*DecodePreviewResponse, error)
	// Messages (listing + streaming + search/export)
	ListMessages(context.Context, *ListMessagesRequest) (*ListMessagesResponse, error)
	StreamMessages(*StreamMessagesRequest, grpc.ServerStreamingServer[Message]) error
	ListBaseStationMessages(context.Context, *ListBaseStationMessagesRequest) (*ListBaseStationMessagesResponse, error)
	GetBaseStationMessage(context.Context, *GetBaseStationMessageRequest) (*GetBaseStationMessageResponse, error)
	GetBaseStationMessageStats(context.Context, *GetBaseStationMessageStatsRequest) (*GetBaseStationMessageStatsResponse, error)
	SearchBaseStationMessages(context.Context, *SearchBaseStationMessagesRequest) (*SearchBaseStationMessagesResponse, error)
	ExportBaseStationMessages(context.Context, *ExportBaseStationMessagesRequest) (*ExportBaseStationMessagesResponse, error)
	StreamBaseStationMessages(*StreamBaseStationMessagesRequest, grpc.ServerStreamingServer[BaseStationMessage]) error
	// Endpoint-specific message listing
	ListEndpointMessages(context.Context, *ListEndpointMessagesRequest) (*ListEndpointMessagesResponse, error)
	// Endpoint Stats/Operations
	GetEndPointStats(context.Context, *GetEndPointStatsRequest) (*GetEndPointStatsResponse, error)
	GetEndPointOperations(context.Context, *GetEndPointOperationsRequest) (*GetEndPointOperationsResponse, error)
	// Global coverage (server admin only — cross-tenant)
	ListAllBaseStationLocations(context.Context, *ListAllBaseStationLocationsRequest) (*ListAllBaseStationLocationsResponse, error)
	// CE onboarding (CE mode only — requires no authentication)
	GetCEStatus(context.Context, *GetCEStatusRequest) (*GetCEStatusResponse, error)
	CompleteCEOnboarding(context.Context, *CompleteCEOnboardingRequest) (*CompleteCEOnboardingResponse, error)
	// ECE CE registry admin (ECE internal only)
	ListCEInstances(context.Context, *ListCEInstancesRequest) (*ListCEInstancesResponse, error)
	RevokeCEInstance(context.Context, *RevokeCEInstanceRequest) (*RevokeCEInstanceResponse, error)
}

